import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // root container
  const root = new Group();

  // plane geometry (unit size, will be scaled by scenePosition)
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // render text items
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: (config.visualSpec?.colors?.paper) ?? '#e8ecf2',
      align: 'center',
    });
    // place text slightly above the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // apply cinematic primitives defined in the config
  const activePrimitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(root, prim.params);
        activePrimitives.push(result);
      }
    }
  }

  // placeholder for event handlers (none in this spec)
  root.userData.handlers = {};

  // cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    activePrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    // no GSAP timelines were created for this node, but clear any that might exist
    // (defensive – does not affect other nodes)
    gsap.globalTimeline.clear();
  };

  return root;
}
